#!/usr/bin/env node
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import { compile } from "json-schema-to-typescript";

const toolDirectory = path.dirname(fileURLToPath(import.meta.url));
const repositoryRoot = path.resolve(toolDirectory, "../..");
const generatedRoot = path.join(
  repositoryRoot,
  "packages/protocol-ts/src/generated",
);
const generatedMarker =
  "// Code generated by tools/protocol-ts/generate-protocol-types.mjs; DO NOT EDIT.";

function readJSON(relativePath) {
  return JSON.parse(readFileSync(path.join(repositoryRoot, relativePath), "utf8"));
}

function requireObject(value, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be an object`);
  }
  return value;
}

function requireString(value, label) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new Error(`${label} must be a non-empty string`);
  }
  return value;
}

function requireStringArray(value, label) {
  if (!Array.isArray(value) || value.length === 0) {
    throw new Error(`${label} must be a non-empty array`);
  }
  return value.map((entry, index) =>
    requireString(entry, `${label}[${index}]`),
  );
}

function pascalCase(value) {
  return value
    .split(/[^A-Za-z0-9]+/u)
    .filter(Boolean)
    .map((part) => `${part[0].toUpperCase()}${part.slice(1)}`)
    .join("");
}

function cloneWithRewrittenReferences(value, fromPrefix, toPrefix) {
  if (Array.isArray(value)) {
    return value.map((entry) =>
      cloneWithRewrittenReferences(entry, fromPrefix, toPrefix),
    );
  }
  if (!value || typeof value !== "object") {
    return value;
  }
  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [
      key,
      key === "$ref" && typeof entry === "string"
        ? entry.replace(fromPrefix, toPrefix)
        : cloneWithRewrittenReferences(entry, fromPrefix, toPrefix),
    ]),
  );
}

function referencedDefinitionNames(value, referencePrefix) {
  const names = new Set();
  const visit = (entry) => {
    if (Array.isArray(entry)) {
      entry.forEach(visit);
      return;
    }
    if (!entry || typeof entry !== "object") {
      return;
    }
    for (const [key, child] of Object.entries(entry)) {
      if (
        key === "$ref" &&
        typeof child === "string" &&
        child.startsWith(referencePrefix)
      ) {
        names.add(child.slice(referencePrefix.length));
      } else {
        visit(child);
      }
    }
  };
  visit(value);
  return names;
}

function definitionClosure(allDefinitions, entrypointNames) {
  const selected = new Map();
  const pending = [...entrypointNames];
  while (pending.length > 0) {
    const name = pending.shift();
    if (selected.has(name)) {
      continue;
    }
    const definition = allDefinitions[name];
    if (definition === undefined) {
      throw new Error(`missing referenced schema definition ${name}`);
    }
    selected.set(name, definition);
    for (const referenced of referencedDefinitionNames(
      definition,
      "#/$defs/",
    )) {
      pending.push(referenced);
    }
  }
  return Object.fromEntries(selected);
}

function schemaBundle(id, definitions) {
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: id,
    $defs: definitions,
  };
}

function publicDefinitionsBySchemaID(networkFlowIndex, networkFlowSchema) {
  const definitions = requireObject(networkFlowSchema.$defs, "network-flow $defs");
  const publicSchemaIDs = requireStringArray(
    networkFlowIndex.public_schema_ids,
    "network-flow public_schema_ids",
  );
  const bySchemaID = new Map();
  for (const [name, rawDefinition] of Object.entries(definitions)) {
    const definition = requireObject(rawDefinition, `network-flow $defs.${name}`);
    if (typeof definition.x_schema_id === "string") {
      if (bySchemaID.has(definition.x_schema_id)) {
        throw new Error(`duplicate Network Flow schema id ${definition.x_schema_id}`);
      }
      bySchemaID.set(definition.x_schema_id, name);
    }
  }
  for (const schemaID of publicSchemaIDs) {
    if (!bySchemaID.has(schemaID)) {
      throw new Error(`missing Network Flow definition for ${schemaID}`);
    }
  }
  if (bySchemaID.size !== publicSchemaIDs.length) {
    throw new Error("Network Flow public schema index and x_schema_id definitions drifted");
  }
  return new Map(publicSchemaIDs.map((schemaID) => [schemaID, bySchemaID.get(schemaID)]));
}

function collaborationDefinitions(wsIndex, expectedMessageTypes) {
  const messages = wsIndex?.properties?.messages?.default;
  if (!Array.isArray(messages)) {
    throw new Error("collaboration contract is missing messages.default");
  }
  const definitions = {};
  const schemaIDs = new Map();
  const actualMessageTypes = [];
  for (const entry of messages) {
    const type = requireString(entry?.type, "collaboration message type");
    actualMessageTypes.push(type);
    const name = `${pascalCase(type)}Message`;
    const schemaID = `cartulary.ws.${type}.v1`;
    definitions[name] = {
      x_schema_id: schemaID,
      type: "object",
      additionalProperties: true,
      properties: {
        type: { const: type },
        payload: requireObject(
          entry.payload_schema ?? { type: "object" },
          `collaboration ${type} payload_schema`,
        ),
        ...(entry.replayable === true
          ? { stream_seq: { type: "integer", minimum: 1 } }
          : {}),
      },
      required: [
        "type",
        "payload",
        ...(entry.replayable === true ? ["stream_seq"] : []),
      ],
    };
    schemaIDs.set(schemaID, name);
  }
  if (
    actualMessageTypes.length !== expectedMessageTypes.length ||
    actualMessageTypes.some((type, index) => type !== expectedMessageTypes[index])
  ) {
    throw new Error("collaboration entrypoint message types drifted from the WS contract");
  }
  definitions.IncidentStreamMessage = {
    oneOf: [...schemaIDs.values()].map((name) => ({ $ref: `#/$defs/${name}` })),
  };
  schemaIDs.set("cartulary.ws.incident_stream_message.v1", "IncidentStreamMessage");
  return { definitions, schemaIDs };
}

async function generatedTypes(bundle, rootName) {
  const compiled = await compile(bundle, rootName, {
    bannerComment: generatedMarker,
    cwd: repositoryRoot,
    style: { singleQuote: false },
    unreachableDefinitions: true,
  });
  return compiled.endsWith("\n") ? compiled : `${compiled}\n`;
}

function validatorSource(entries) {
  const ajv = new Ajv2020({
    allErrors: true,
    code: { esm: true, source: true },
    strict: true,
    strictRequired: false,
  });
  ajv.addKeyword("x_schema_id");
  ajv.addFormat(
    "uuid",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu,
  );
  ajv.addFormat("date-time", true);

  const exports = {};
  for (const entry of entries) {
    ajv.addSchema(entry.bundle);
    for (const [schemaID, definitionName] of entry.publicDefinitions) {
      const wrapperID = `${entry.bundle.$id}/${encodeURIComponent(schemaID)}`;
      ajv.addSchema({
        $schema: "https://json-schema.org/draft/2020-12/schema",
        $id: wrapperID,
        $ref: `${entry.bundle.$id}#/$defs/${definitionName}`,
      });
      exports[`validate${pascalCase(schemaID)}`] = wrapperID;
    }
  }
  const source = standaloneCode(ajv, exports)
    .replace(
      /const (func\d+) = require\("ajv\/dist\/runtime\/ucs2length"\)\.default;/gu,
      "const $1 = cartularyUcs2Length;",
    )
    .replace(
      /const (func\d+) = require\("ajv\/dist\/runtime\/equal"\)\.default;/gu,
      "const $1 = cartularyDeepEqual;",
    );
  return `${generatedMarker}\n// @ts-nocheck\nimport cartularyDeepEqual from "ajv/dist/runtime/equal.js";\nimport cartularyUcs2Length from "ajv/dist/runtime/ucs2length.js";\n${source}\n`;
}

function generatedConstSource(exportName, value) {
  return `${generatedMarker}\n\nexport const ${exportName} = ${JSON.stringify(
    value,
    null,
    2,
  )} as const;\n`;
}

const entrypoints = readJSON(
  "contracts/network-flow/frontend-entrypoints.v1.json",
);
const networkFlowConfig = requireObject(entrypoints.network_flow, "network_flow");
const networkFlowIndex = readJSON(
  requireString(networkFlowConfig.contract_index_path, "network_flow.contract_index_path"),
);
const networkFlowSchema = readJSON(
  requireString(networkFlowConfig.schema_bundle_path, "network_flow.schema_bundle_path"),
);
const networkFlowPresentation = readJSON(
  requireString(networkFlowConfig.presentation_path, "network_flow.presentation_path"),
);
const networkFlowMappingRegistry = readJSON(
  requireString(networkFlowConfig.mapping_registry_path, "network_flow.mapping_registry_path"),
);
for (const [label, artifact, schemaID] of [
  ["presentation", networkFlowPresentation, "cartulary.network_flow.presentation.v1"],
  ["mapping registry", networkFlowMappingRegistry, "cartulary.network_flow.mapping_registry.v1"],
]) {
  requireObject(artifact, `network-flow ${label}`);
  if (artifact.schema_id !== schemaID) {
    throw new Error(`network-flow ${label} has unexpected schema_id`);
  }
  if (artifact.document_version !== networkFlowIndex.document_version) {
    throw new Error(`network-flow ${label} document version drifted from index`);
  }
}
const networkFlowDefinitions = requireObject(
  networkFlowSchema.$defs,
  "network-flow definitions",
);
const networkFlowPublicDefinitions = publicDefinitionsBySchemaID(
  networkFlowIndex,
  networkFlowSchema,
);
const networkFlowBundle = schemaBundle(
  "https://contracts.cartulary.local/generated/network-flow-public.v1",
  networkFlowDefinitions,
);

const coreHTTPConfig = requireObject(entrypoints.core_http, "core_http");
const openAPI = readJSON(requireString(coreHTTPConfig.openapi_path, "core_http.openapi_path"));
const openAPIDefinitions = cloneWithRewrittenReferences(
  requireObject(openAPI?.components?.schemas, "OpenAPI components.schemas"),
  "#/components/schemas/",
  "#/$defs/",
);
const coreHTTPEntrypoints = requireStringArray(
  coreHTTPConfig.component_schema_names,
  "core_http.component_schema_names",
);
const coreHTTPDefinitions = definitionClosure(
  openAPIDefinitions,
  coreHTTPEntrypoints,
);
const coreHTTPBundle = schemaBundle(
  "https://contracts.cartulary.local/generated/core-http.v1",
  coreHTTPDefinitions,
);
const coreHTTPPublicDefinitions = new Map(
  coreHTTPEntrypoints.map((name) => [`cartulary.core_http.${name}.v1`, name]),
);

const collaborationConfig = requireObject(
  entrypoints.collaboration,
  "collaboration",
);
const wsIndex = readJSON(
  requireString(
    collaborationConfig.contract_index_path,
    "collaboration.contract_index_path",
  ),
);
const collaboration = collaborationDefinitions(
  wsIndex,
  requireStringArray(
    collaborationConfig.message_types,
    "collaboration.message_types",
  ),
);
const collaborationBundle = schemaBundle(
  "https://contracts.cartulary.local/generated/collaboration.v1",
  collaboration.definitions,
);

writeFileSync(
  path.join(generatedRoot, "network-flow-types.ts"),
  await generatedTypes(networkFlowBundle, "NetworkFlowPublicSchemas"),
);
writeFileSync(
  path.join(generatedRoot, "core-http-types.ts"),
  await generatedTypes(coreHTTPBundle, "CoreHTTPEntrypoints"),
);
writeFileSync(
  path.join(generatedRoot, "collaboration-types.ts"),
  await generatedTypes(collaborationBundle, "CollaborationMessages"),
);
writeFileSync(
  path.join(generatedRoot, "protocol-validators.ts"),
  validatorSource([
    {
      bundle: networkFlowBundle,
      publicDefinitions: networkFlowPublicDefinitions,
    },
    { bundle: coreHTTPBundle, publicDefinitions: coreHTTPPublicDefinitions },
    {
      bundle: collaborationBundle,
      publicDefinitions: collaboration.schemaIDs,
    },
  ]),
);

const descriptor = {
  profile_id: requireString(networkFlowIndex.profile_id, "network-flow profile_id"),
  contract_major: networkFlowIndex.contract_major,
  document_version: requireString(
    networkFlowIndex.document_version,
    "network-flow document_version",
  ),
};
writeFileSync(
  path.join(generatedRoot, "network-flow-descriptor.ts"),
  `${generatedMarker}\n\nexport const networkFlowContractDescriptor = ${JSON.stringify(
    descriptor,
    null,
    2,
  )} as const;\n`,
);
writeFileSync(
  path.join(generatedRoot, "network-flow-presentation.ts"),
  generatedConstSource("networkFlowPresentationRegistry", networkFlowPresentation),
);
writeFileSync(
  path.join(generatedRoot, "network-flow-mapping-registry.ts"),
  generatedConstSource("networkFlowMappingRegistry", networkFlowMappingRegistry),
);

writeFileSync(
  path.join(generatedRoot, "index.ts"),
  `${generatedMarker}\n\nexport * from "./contracts.js";\n`,
);
